import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Focus Trap', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://your-application-url.com');
    await page.getByRole('button', { name: 'Open Modal' }).click();
  });

  test('should keep focus inside the modal when tabbing', async ({ page }) => {
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    const firstFocusable = await modal.getByRole('button', { name: 'First Button' });
    await firstFocusable.focus();
    await page.keyboard.press('Tab');

    const secondFocusable = await modal.getByRole('button', { name: 'Second Button' });
    await expect(secondFocusable).toBeFocused();
  });

  test('should return focus to the first element after last element is tabbed', async ({ page }) => {
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    const lastFocusable = await modal.getByRole('button', { name: 'Last Button' });
    await lastFocusable.focus();
    await page.keyboard.press('Tab');

    const firstFocusable = await modal.getByRole('button', { name: 'First Button' });
    await expect(firstFocusable).toBeFocused();
  });
});
